import raw from '../data/timeline.json';
import type {Chapter, Utterance, Word} from '../engine/narration/types';

// The master timeline is generated by scripts/timeline/build.mjs from the storyboard script and
// the rendered voice. Every scene, caption, Pixie cue and sound hit is placed from these times,
// so re-rendering the voice re-times the whole film without touching scene code.

export interface SceneTime {
  id: string;
  chapter: string;
  start: number;
  end: number;
}

export interface TimedUtterance extends Utterance {
  scene: string;
  start: number;
  end: number;
  plain: string;
}

export interface FilmTimeline {
  fps: number;
  durationS: number;
  durationInFrames: number;
  chapters: Chapter[];
  scenes: SceneTime[];
  utterances: TimedUtterance[];
  /** lookups */
  chapter: (id: string) => Chapter;
  scene: (id: string) => SceneTime;
  utt: (id: string) => TimedUtterance;
  /** a word of an utterance, by index or by its text (first match, case-insensitive, punctuation ignored) */
  word: (uttId: string, which: number | string) => Word;
  /** utterances of a scene, in order */
  sceneUtts: (sceneId: string) => TimedUtterance[];
  /** frame of a time */
  f: (s: number) => number;
}

const clean = (s: string) => s.toLowerCase().replace(/[^a-z0-9%µ.]+/g, '').replace(/\.$/, '');

const build = (): FilmTimeline => {
  const t = raw as unknown as Omit<FilmTimeline, 'chapter' | 'scene' | 'utt' | 'word' | 'sceneUtts' | 'f'>;
  const chapters = new Map(t.chapters.map((c) => [c.id, c]));
  const scenes = new Map(t.scenes.map((s) => [s.id, s]));
  const utts = new Map(t.utterances.map((u) => [u.id, u]));
  const byScene = new Map<string, TimedUtterance[]>();
  for (const u of t.utterances) {
    const list = byScene.get(u.scene) ?? [];
    list.push(u);
    byScene.set(u.scene, list);
  }
  const need = <T,>(m: Map<string, T>, id: string, kind: string): T => {
    const v = m.get(id);
    if (!v) throw new Error(`timeline: unknown ${kind} "${id}"`);
    return v;
  };
  return {
    ...t,
    chapter: (id) => need(chapters, id, 'chapter'),
    scene: (id) => need(scenes, id, 'scene'),
    utt: (id) => need(utts, id, 'utterance'),
    word: (uttId, which) => {
      const u = need(utts, uttId, 'utterance');
      if (typeof which === 'number') {
        const w = u.words[which < 0 ? u.words.length + which : which];
        if (!w) throw new Error(`timeline: ${uttId} has no word ${which}`);
        return w;
      }
      const key = clean(which);
      const w = u.words.find((x) => clean(x.text) === key) ?? u.words.find((x) => clean(x.text).startsWith(key));
      if (!w) throw new Error(`timeline: ${uttId} has no word "${which}"`);
      return w;
    },
    sceneUtts: (id) => byScene.get(id) ?? [],
    f: (s) => Math.round(s * t.fps),
  };
};

export const timeline: FilmTimeline = build();
